              , "| TransitKey : Text"
              , "| Prompt : { name : Text, purpose : Text }"
              , "| TestPlaintext : Text"
              , ">.TestPlaintext \"AKIAEXAMPLE\""
              ]
      decoded <- Dhall.input Dhall.auto expr
      decoded `shouldBe` SecretRefTestPlaintext "AKIAEXAMPLE"
