                  ( NativeNuke
                      ( NukeOptions
                          { nukeDryRun = False
                          , nukePlanFile = Nothing
                          , nukeReceiptPath = Just "/operator/decommission/prodbox.receipt"
                          , nukeLocalDataDisposition = Nothing
                          }
                      )
