    it "renders the full AWS policy with EKS lifecycle statements" $ do
      case buildIamPolicyDocument PolicyFull of
        Object payload -> do
          case KeyMap.lookup (Key.fromString "Statement") payload of
            Just (Array statements) -> do
              let sids =
                    [ sid
                    | Object statement <- Vector.toList statements
                    , Just (String sid) <- [KeyMap.lookup (Key.fromString "Sid") statement]
                    ]
              sids
                `shouldContain` [ "Ec2TestStackLifecycle"
                                , "IamEksRoleLifecycle"
                                , "EksTestStackLifecycle"
                                , "SesCaptureBucketRead"
                                , "SesCaptureObjectRead"
                                , "SesReadOnly"
                                ]
            _ -> expectationFailure "expected Statement array"
        _ -> expectationFailure "expected policy document object"

    it "installs an account- and capture-qualified bounded SES pre-lease policy" $ do
      let policyResult =
            buildIamPolicyDocumentForAccountAndCaptureBucket
              "123456789012"
              (Just "configured-ses-capture")
              PolicyFull
      case policyResult of
        Left err -> expectationFailure (show err)
        Right policy -> do
          let rendered = encode policy
              renderedText = BL8.unpack rendered
          BL.length rendered `shouldSatisfy` (<= 2048)
          renderedText
            `shouldContain` "arn:aws:iam::123456789012:role/prodbox-ses-lease-session"
          renderedText
            `shouldContain` "arn:aws:iam::123456789012:user/prodbox-ses-smtp"
          renderedText
            `shouldContain` "arn:aws:s3:::configured-ses-capture"
          renderedText `shouldNotContain` "arn:aws:iam::*:role/prodbox-ses-lease-session"

    it "omits capture reads until a valid configured bucket is available" $ do
      case buildIamPolicyDocumentForAccountAndCaptureBucket
        "123456789012"
        Nothing
        PolicyFull of
        Left err -> expectationFailure (show err)
        Right policy -> BL8.unpack (encode policy) `shouldNotContain` "SesCaptureRead"
      buildIamPolicyDocumentForAccountAndCaptureBucket
        "123456789012"
        (Just "Bad_Bucket")
        PolicyFull
        `shouldSatisfy` isLeft

    it "builds disjoint least-privilege adapter IAM policies" $ do
      authorityBackupIamUserName `shouldBe` "prodbox-authority-backup-store"
      tlsRetentionIamUserName `shouldBe` "prodbox-tls-retention-store"
      let backup =
            buildDedicatedAdapterIamPolicyDocument
              "prodbox-retained"
              ["authority-backup-store/home", "authority-backup-store/aws-eks-test"]
          tls =
            buildDedicatedAdapterIamPolicyDocument
              "prodbox-retained"
              [ "public-edge-tls/home-local/test.example.com"
              , "public-edge-tls/aws/aws.test.example.com"
              ]
      case (backup, tls) of
        (Right backupPolicy, Right tlsPolicy) -> do
          let backupText = BL8.unpack (encode backupPolicy)
              tlsText = BL8.unpack (encode tlsPolicy)
          backupText `shouldContain` "arn:aws:s3:::prodbox-retained/authority-backup-store/home/*"
          backupText `shouldContain` "s3:GetObject"
          backupText `shouldContain` "s3:PutObject"
          backupText `shouldContain` "s3:ListBucket"
          backupText `shouldNotContain` "public-edge-tls"
          backupText `shouldNotContain` "s3:DeleteObject"
          backupText `shouldNotContain` "iam:"
          tlsText
            `shouldContain` "arn:aws:s3:::prodbox-retained/public-edge-tls/home-local/test.example.com/*"
          tlsText `shouldNotContain` "authority-backup-store"
          tlsText `shouldNotContain` "s3:DeleteObject"
        other -> expectationFailure ("expected dedicated IAM policies, got " ++ show other)
      buildDedicatedAdapterIamPolicyDocument
        "prodbox-retained"
        ["authority-backup-store/*"]
        `shouldSatisfy` isLeft
      buildDedicatedAdapterIamPolicyDocument
        "prodbox-retained"
        ["public-edge-tls/home-local/*"]
        `shouldSatisfy` isLeft

