      lookupPrerequisiteEffect "infra_ready" `shouldBe` Noop
      lookupPrerequisiteEffect "public_edge_ready" `shouldBe` Noop
      lookupPrerequisiteEffect "gateway_daemon_acquire" `shouldBe` Noop

