                         , "  , sync_interval_seconds = 5.0"
                         , "  , max_clock_skew_seconds = 10.0"
                         , "  , drain_deadline_seconds = None Natural"
                         , "  , log_level = None Text"
                         , "  }"
                         , "}"
                         ]
                  )
              )
      result <- GatewaySettings.decodeDaemonConfigDhall mismatched
      case result of
