        Left err -> err `shouldContain` "config_schema_mismatch"

    it "fails fast when a required boot field is empty" $ do
      let emptyNode =
            Text.pack
              ( unlines
                  ( [ "{ schemaVersion = 1"
                    ]
                      ++ gatewayVaultNoneLines
                      ++ [ ", boot ="
                         , "  { node_id = \"\""
                         , "  , cert_file = \"a.crt\""
                         , "  , key_file = \"a.key\""
                         , "  , ca_file = \"ca.crt\""
