      case result of
        Left err -> expectationFailure err
        Right dto -> do
          WorkloadSettings.mode dto `shouldBe` WorkloadSettings.Websocket
          WorkloadSettings.log_level dto `shouldBe` Just "debug"
          case WorkloadSettings.redis dto of
            Just r -> WorkloadSettings.host r `shouldBe` "redis"
            Nothing -> expectationFailure "expected Some redis config"

    it "fails fast on schemaVersion mismatch" $ do
      let mismatched =
            Text.pack
              ( unlines
                  [ "{ schemaVersion = 99"
                  , ", mode = < Api | Websocket >.Api"
                  , ", log_level = None Text"
                  , ", workload_port = None Natural"
                  , ", vault = None"
                  , "    { address : Text"
                  , "    , auth_path : Text"
                  , "    , role : Text"
                  , "    , service_account_token_file : Optional Text"
                  , "    }"
                  , ", redis = None { host : Text, port : Text }"
                  , ", oidc = None"
                  , "    { issuer : Text"
                  , "    , client_id : Text"
                  , "    , client_secret :"
                  , "        < Vault : { mount : Text, path : Text, field : Text }"
                  , "        | TransitKey : Text"
                  , "        | Prompt : { name : Text, purpose : Text }"
                  , "        | TestPlaintext : Text"
                  , "        >"
                  , "    , public_base_url : Text"
                  , "    , token_endpoint : Text"
                  , "    }"
                  , "}"
                  ]
              )
      result <- WorkloadSettings.decodeWorkloadConfigDhall mismatched
      case result of
        Right _ -> expectationFailure "expected schemaVersion mismatch failure"
        Left err -> err `shouldContain` "config_schema_mismatch"

  describe "Sprint 3.15 workload Boot/Live config split" $ do
    let decodeWorkload src = do
          result <- WorkloadSettings.decodeWorkloadConfigDhall (Text.pack (unlines src))
          case result of
            Left err -> expectationFailure err >> error "unreachable"
            Right dto -> pure dto
        buildLive =
          workloadLiveConfigFromDhallWith (resolveSecretRef TestHarnessMode)
        vaultNone =
          [ ", vault = None"
          , "    { address : Text"
          , "    , auth_path : Text"
          , "    , role : Text"
          , "    , service_account_token_file : Optional Text"
          , "    }"
          ]
        oidcType =
          [ "    { issuer : Text"
          , "    , client_id : Text"
          , "    , client_secret :"
          , "        < Vault : { mount : Text, path : Text, field : Text }"
          , "        | TransitKey : Text"
          , "        | Prompt : { name : Text, purpose : Text }"
          , "        | TestPlaintext : Text"
          , "        >"
          , "    , public_base_url : Text"
          , "    , token_endpoint : Text"
          , "    }"
          ]
        testPlaintextSecret =
          [ "    , client_secret ="
          , "        < Vault : { mount : Text, path : Text, field : Text }"
          , "        | TransitKey : Text"
          , "        | Prompt : { name : Text, purpose : Text }"
          , "        | TestPlaintext : Text"
          , "        >.TestPlaintext \"secret\""
          ]
        apiSrc =
          [ "{ schemaVersion = 1"
          , ", mode = < Api | Websocket >.Api"
          , ", log_level = None Text"
          , ", workload_port = Some 8080"
          ]
            ++ vaultNone
            ++ [ ", redis = None { host : Text, port : Text }"
               , ", oidc = None"
               ]
            ++ oidcType
            ++ [ "}"
               ]
        websocketSrc logLevelLine portLine redisLine =
          [ "{ schemaVersion = 1"
          , ", mode = < Api | Websocket >.Websocket"
          , logLevelLine
          , portLine
          ]
            ++ vaultNone
            ++ [ redisLine
               , ", oidc = Some"
               , "    { issuer = \"https://test.example.com/auth/realms/r\""
               , "    , client_id = \"prodbox\""
               ]
            ++ testPlaintextSecret
            ++ [ "    , public_base_url = \"https://test.example.com\""
               , "    , token_endpoint = \"/token\""
               , "    }"
               , "}"
               ]

    it "classifies mode and port as Boot fields and log_level as a Live field" $ do
      dto <- decodeWorkload apiSrc
      let boot = workloadBootConfigFromDhall dto
      bootMode boot `shouldBe` WorkloadApi
      bootPort boot `shouldBe` 8080
      liveResult <- buildLive (bootMode boot) dto
      case liveResult of
        Left err -> expectationFailure err
        Right live -> do
          liveLogLevel live `shouldBe` "info"
          liveRedisConfig live `shouldBe` Nothing
          liveOidcConfig live `shouldBe` Nothing

    it "defaults the listen port to 8080 when workload_port is None" $ do
      dto <-
        decodeWorkload
          ( [ "{ schemaVersion = 1"
            , ", mode = < Api | Websocket >.Api"
            , ", log_level = None Text"
            , ", workload_port = None Natural"
            ]
              ++ vaultNone
              ++ [ ", redis = None { host : Text, port : Text }"
                 , ", oidc = None"
                 ]
              ++ oidcType
              ++ [ "}"
                 ]
          )
      bootPort (workloadBootConfigFromDhall dto) `shouldBe` 8080

    it "treats a log_level edit as a Live change (no Boot-field change)" $ do
      original <-
        decodeWorkload
          ( websocketSrc
              ", log_level = Some \"info\""
              ", workload_port = Some 8081"
              ", redis = Some { host = \"redis\", port = \"6379\" }"
          )
      edited <-
        decodeWorkload
          ( websocketSrc
              ", log_level = Some \"debug\""
              ", workload_port = Some 8081"
              ", redis = Some { host = \"redis\", port = \"6379\" }"
          )
      workloadBootFieldsChanged
        (workloadBootConfigFromDhall original)
        (workloadBootConfigFromDhall edited)
        `shouldBe` False
      liveResult <- buildLive WorkloadWebsocket edited
      case liveResult of
        Left err -> expectationFailure err
        Right live -> liveLogLevel live `shouldBe` "debug"

    it "treats a Redis-endpoint edit as a Live change (no Boot-field change)" $ do
      original <-
        decodeWorkload
          ( websocketSrc
              ", log_level = Some \"info\""
              ", workload_port = Some 8081"
              ", redis = Some { host = \"redis\", port = \"6379\" }"
          )
      edited <-
        decodeWorkload
          ( websocketSrc
              ", log_level = Some \"info\""
              ", workload_port = Some 8081"
              ", redis = Some { host = \"redis-2\", port = \"6380\" }"
          )
      workloadBootFieldsChanged
        (workloadBootConfigFromDhall original)
        (workloadBootConfigFromDhall edited)
        `shouldBe` False
      originalLiveResult <- buildLive WorkloadWebsocket original
      editedLiveResult <- buildLive WorkloadWebsocket edited
      case (originalLiveResult, editedLiveResult) of
        (Right originalLive, Right editedLive) ->
          liveRedisConfig editedLive `shouldNotBe` liveRedisConfig originalLive
        _ -> expectationFailure "expected both websocket live configs to build"

    it "treats a port edit as a Boot-field change (drain-and-exit)" $ do
      original <-
        decodeWorkload
          ( websocketSrc
              ", log_level = Some \"info\""
              ", workload_port = Some 8081"
              ", redis = Some { host = \"redis\", port = \"6379\" }"
          )
      edited <-
        decodeWorkload
          ( websocketSrc
              ", log_level = Some \"info\""
              ", workload_port = Some 9090"
              ", redis = Some { host = \"redis\", port = \"6379\" }"
          )
      workloadBootFieldsChanged
        (workloadBootConfigFromDhall original)
        (workloadBootConfigFromDhall edited)
        `shouldBe` True

    it "treats a mode edit as a Boot-field change (drain-and-exit)" $ do
      apiDto <- decodeWorkload apiSrc
      websocketDto <-
        decodeWorkload
          ( websocketSrc
              ", log_level = None Text"
              ", workload_port = Some 8080"
              ", redis = Some { host = \"redis\", port = \"6379\" }"
          )
      workloadBootFieldsChanged
        (workloadBootConfigFromDhall apiDto)
        (workloadBootConfigFromDhall websocketDto)
        `shouldBe` True

    it "rejects test plaintext on the default production workload resolver" $ do
      dto <-
        decodeWorkload
          ( websocketSrc
              ", log_level = None Text"
              ", workload_port = Some 8080"
              ", redis = Some { host = \"redis\", port = \"6379\" }"
          )
      liveResult <- workloadLiveConfigFromDhall WorkloadWebsocket dto
      case liveResult of
        Right _ -> expectationFailure "expected production resolver to reject TestPlaintext"
        Left err -> err `shouldContain` "plaintext secret values are forbidden"

    it "fails the live-config build when a websocket config omits redis" $ do
      dto <-
        decodeWorkload
          ( [ "{ schemaVersion = 1"
            , ", mode = < Api | Websocket >.Websocket"
            , ", log_level = None Text"
            , ", workload_port = Some 8081"
            ]
              ++ vaultNone
              ++ [ ", redis = None { host : Text, port : Text }"
                 , ", oidc = Some"
                 , "    { issuer = \"https://test.example.com\""
                 , "    , client_id = \"prodbox\""
                 ]
              ++ testPlaintextSecret
              ++ [ "    , public_base_url = \"https://test.example.com\""
                 , "    , token_endpoint = \"/token\""
                 , "    }"
                 , "}"
                 ]
          )
      liveResult <- buildLive WorkloadWebsocket dto
      case liveResult of
        Right _ -> expectationFailure "expected a structured failure when redis is None"
        Left err -> err `shouldContain` "redis must be Some"

    it "fails fast when the workload binary is started without --config" $ do
      exitCode <- runWorkloadCommand (WorkloadStart (WorkloadOptions {workloadConfigPath = Nothing}))
      exitCode `shouldBe` ExitFailure 1

    it "fails fast when the workload --config path does not exist" $ do
      exitCode <-
        runWorkloadCommand
          (WorkloadStart (WorkloadOptions {workloadConfigPath = Just "/nonexistent/workload/config.dhall"}))
      exitCode `shouldBe` ExitFailure 1

  describe "Sprint 3.13 in-cluster K8s API client pure helpers" $ do
    it "exposes the canonical in-pod ServiceAccount mount paths" $ do
      InCluster.inClusterServiceAccountDir
        `shouldBe` "/var/run/secrets/kubernetes.io/serviceaccount"
      InCluster.inClusterTokenPath
        `shouldBe` "/var/run/secrets/kubernetes.io/serviceaccount/token"
      InCluster.inClusterCaCertPath
        `shouldBe` "/var/run/secrets/kubernetes.io/serviceaccount/ca.crt"
      InCluster.inClusterNamespacePath
        `shouldBe` "/var/run/secrets/kubernetes.io/serviceaccount/namespace"

    it "secretApiBaseUrl points at the in-cluster kube-apiserver Service" $
      InCluster.secretApiBaseUrl
        `shouldBe` "https://kubernetes.default.svc.cluster.local:443"

    it "secretApiPath renders the namespaced v1.Secret REST path" $ do
      InCluster.secretApiPath "keycloak" "keycloak-runtime"
        `shouldBe` "/api/v1/namespaces/keycloak/secrets/keycloak-runtime"
      InCluster.secretApiPath "default" "prodbox-keycloak-pg-pguser-postgres"
        `shouldBe` "/api/v1/namespaces/default/secrets/prodbox-keycloak-pg-pguser-postgres"

    it "secretManifestJson encodes apiVersion / kind / type / metadata / stringData" $ do
      let manifest =
            InCluster.secretManifestJson
              "keycloak"
              "keycloak-runtime"
              (Map.fromList [("KEYCLOAK_ADMIN_PASSWORD", "secret-value")])
          rendered = BL8.unpack (encode manifest)
      rendered `shouldContain` "\"apiVersion\":\"v1\""
      rendered `shouldContain` "\"kind\":\"Secret\""
      rendered `shouldContain` "\"type\":\"Opaque\""
      rendered `shouldContain` "\"name\":\"keycloak-runtime\""
      rendered `shouldContain` "\"namespace\":\"keycloak\""
      rendered `shouldContain` "\"KEYCLOAK_ADMIN_PASSWORD\":\"secret-value\""

    it "secretManifestStringData emits keys in ascending lexical order (deterministic)" $ do
      let rendered =
            BL8.unpack
              ( encode
                  ( InCluster.secretManifestStringData
                      (Map.fromList [("z", "1"), ("a", "2"), ("m", "3")])
                  )
              )
      rendered `shouldBe` "{\"a\":\"2\",\"m\":\"3\",\"z\":\"1\"}"

    it "secretManifestStringData round-trips with itself (purity invariant)" $ do
      let dataMap = Map.fromList [("user", "alice"), ("pass", "p@ss")]
      InCluster.secretManifestStringData dataMap
        `shouldBe` InCluster.secretManifestStringData dataMap

    it "secretManifestStringData handles an empty stringData map" $ do
      BL8.unpack (encode (InCluster.secretManifestStringData Map.empty))
        `shouldBe` "{}"

  describe "Sprint 4.16 ResidueStatus typed predicates" $ do
    it "residuePresentByFileExistence returns ResidueAbsent when the file is missing" $
      Residue.residuePresentByFileExistence "aws-eks" "/some/snapshot.json" False
        `shouldBe` Residue.ResidueAbsent

    it
      "residuePresentByFileExistence returns ResiduePresent with file-existence evidence when the file is present"
      $ Residue.residuePresentByFileExistence "aws-eks" "/some/snapshot.json" True
        `shouldBe` Residue.ResiduePresent
          Residue.ResidueDetails
            { Residue.residueEvidence = "file-existence: /some/snapshot.json"
            , Residue.residueStackName = "aws-eks"
            }

    it "isResidueAbsent is the only constructor that matches absent" $ do
      Residue.isResidueAbsent Residue.ResidueAbsent `shouldBe` True
      Residue.isResidueAbsent (Residue.ResiduePresent residueFixtureDetails) `shouldBe` False
      Residue.isResidueAbsent (Residue.ResidueUnreachable residueFixtureMinioReason) `shouldBe` False

    it "isResiduePresent is the only constructor that matches present" $ do
      Residue.isResiduePresent (Residue.ResiduePresent residueFixtureDetails) `shouldBe` True
      Residue.isResiduePresent Residue.ResidueAbsent `shouldBe` False
      Residue.isResiduePresent (Residue.ResidueUnreachable residueFixtureMinioReason) `shouldBe` False

    it "isResidueUnreachable is the only constructor that matches unreachable" $ do
      Residue.isResidueUnreachable (Residue.ResidueUnreachable residueFixtureMinioReason) `shouldBe` True
      Residue.isResidueUnreachable Residue.ResidueAbsent `shouldBe` False
      Residue.isResidueUnreachable (Residue.ResiduePresent residueFixtureDetails) `shouldBe` False

    it "Sprint 4.20 residueBlocksTeardownGate: present OR unreachable blocks, only absent passes" $ do
      Residue.residueBlocksTeardownGate (Residue.ResidueUnreachable residueFixtureMinioReason)
        `shouldBe` True
      Residue.residueBlocksTeardownGate (Residue.ResidueUnreachable residueFixtureS3Reason)
        `shouldBe` True
      Residue.residueBlocksTeardownGate (Residue.ResiduePresent residueFixtureDetails)
        `shouldBe` True
      Residue.residueBlocksTeardownGate Residue.ResidueAbsent `shouldBe` False

    it "renderResidueStatus produces operator-readable evidence per constructor" $ do
      Residue.renderResidueStatus Residue.ResidueAbsent `shouldBe` "absent"
      Residue.renderResidueStatus (Residue.ResiduePresent residueFixtureDetails)
        `shouldBe` "present (aws-eks; evidence: file-existence: /some/snapshot.json)"
      Residue.renderResidueStatus (Residue.ResidueUnreachable residueFixtureMinioReason)
        `shouldBe` "unreachable (MinIO backend unreachable: connection refused)"

    it "renderResidueUnreachableReason discriminates the four reason constructors" $ do
      Residue.renderResidueUnreachableReason (Residue.ResidueBackendMinioUnreachable "x")
        `shouldBe` "MinIO backend unreachable: x"
      Residue.renderResidueUnreachableReason (Residue.ResidueBackendS3Unreachable "y")
        `shouldBe` "S3 backend unreachable: y"
      Residue.renderResidueUnreachableReason (Residue.ResidueQueryFailed "z")
        `shouldBe` "backend query failed: z"
      Residue.renderResidueUnreachableReason (Residue.ResidueQueryNotImplemented "ev")
        `shouldBe` "source-of-truth query not yet implemented (ev)"

    it "renderResidueDetails includes both stack name and evidence string" $
      Residue.renderResidueDetails residueFixtureDetails
        `shouldBe` "aws-eks; evidence: file-existence: /some/snapshot.json"

    it "ResidueStatus values are Eq-comparable by constructor and payload" $ do
      (Residue.ResidueAbsent == Residue.ResidueAbsent) `shouldBe` True
      (Residue.ResiduePresent residueFixtureDetails == Residue.ResiduePresent residueFixtureDetails)
        `shouldBe` True
      (Residue.ResiduePresent residueFixtureDetails == Residue.ResidueAbsent) `shouldBe` False
      ( Residue.ResidueUnreachable residueFixtureMinioReason
          == Residue.ResidueUnreachable residueFixtureS3Reason
        )
        `shouldBe` False

    -- Sprint 4.81 (Standard C): this case asserted `residueAbsent == ResidueAbsent`
    -- for an alias with no production caller -- a tautology about a redundant
    -- second minter, which is the enforcing-nothing shape Sprints 4.68, 4.72,
    -- and 4.77 each found. The alias is withdrawn (chaos_hardening_doctrine
    -- section 23, "count the encoders"), and the case is replaced by one that
    -- pins the property the withdrawal was for: absence has one minter.
    it "has exactly one way to mint an absent residue status" $
      Residue.ResidueAbsent `shouldBe` (Residue.ResidueAbsent :: Residue.ResidueStatus)

  describe "Sprint 4.21 registry per-run reconcile (resourcesToDestroy / pairPerRunResidue)" $ do
    let answers eks sub test =
          ResourceRegistry.PerRunResidueAnswers
            { ResourceRegistry.perRunAnswerAwsEks = eks
            , ResourceRegistry.perRunAnswerAwsEksSubzone = sub
            , ResourceRegistry.perRunAnswerAwsTest = test
            }
        presentNames eks sub test =
          map
            ResourceRegistry.resourceName
            ( ResourceRegistry.resourcesToDestroy
                (ResourceRegistry.pairPerRunResidue (answers eks sub test))
            )

    it "pairPerRunResidue lists the per-run resources in canonical order" $
      map
        (ResourceRegistry.resourceName . fst)
        ( ResourceRegistry.pairPerRunResidue
            (answers Residue.ResidueAbsent Residue.ResidueAbsent Residue.ResidueAbsent)
        )
        `shouldBe` ["aws-eks", "aws-eks-subzone", "aws-test"]

    -- Sprint 4.84: the join was `zip perRunManagedResources [eks, sub, test]`,
    -- so it was correct only while two independently written orders agreed.
    -- Both sides are now selected by the same identity, and these pin that the
    -- identity really does address both.
    it "Sprint 4.84 pairs each registry entry with its own stack's observation" $ do
      let pairsFor eks sub test =
            [ (ResourceRegistry.resourceName resource, status)
            | (resource, status) <- ResourceRegistry.pairPerRunResidue (answers eks sub test)
            ]
      pairsFor residueFixturePresent Residue.ResidueAbsent Residue.ResidueAbsent
        `shouldBe` [ ("aws-eks", residueFixturePresent)
                   , ("aws-eks-subzone", Residue.ResidueAbsent)
                   , ("aws-test", Residue.ResidueAbsent)
                   ]
      pairsFor Residue.ResidueAbsent Residue.ResidueAbsent residueFixturePresent
        `shouldBe` [ ("aws-eks", Residue.ResidueAbsent)
                   , ("aws-eks-subzone", Residue.ResidueAbsent)
                   , ("aws-test", residueFixturePresent)
                   ]

    -- Sprint 4.84: `resourceClass` was a third independent statement of a
    -- resource's lifecycle class, after the typed teardown registry and
    -- `resourceLifecycleClasses`, with nothing joining it to either — and it
    -- is not decorative: it selects the operator-facing scope label for a
    -- destructive reconcile batch, while `resourceLifecycleClasses` is the
    -- table `guardTestDelete` refuses against.
    -- Sprint 4.85: the typed -> flat join cannot see a flat row the typed
    -- registry never registered, which is exactly how the dns-aws validation
    -- hosted zone stayed out of every compiled cleanup program while being
    -- registered, swept by the harness, and billable. This is the other
    -- direction.
    it "Sprint 4.85 every flat inventory row is registered or explicitly exempt" $ do
      Prodbox.CheckCode.untypedLifecycleInventoryViolations `shouldBe` []
      -- Not vacuous: exemptions exist, each carries a stated reason, and none
      -- names a resource the typed registry does register.
      Prodbox.CheckCode.untypedLifecycleInventoryExemptions
        `shouldSatisfy` (not . null)
      map snd Prodbox.CheckCode.untypedLifecycleInventoryExemptions
        `shouldSatisfy` all (not . null)
      -- The exemption list and the typed registry are disjoint. Asserting the
      -- property rather than one row is what survives a row moving between
      -- them: `dns-aws-validation-hosted-zone` was briefly registered and is
      -- exempt again until Sprint 7.36 supplies its Route 53 adapter.
      map fst Prodbox.CheckCode.untypedLifecycleInventoryExemptions
        `shouldSatisfy` all
          ( \name ->
              name
                `notElem` [ Text.unpack
                              ( TeardownModel.registeredResourceKeyText
                                  (TeardownRegistry.managedResourceKey descriptor)
                              )
                          | TeardownRegistry.SomeManagedResourceDescriptor descriptor <-
                              TeardownRegistry.managedResourceRegistry
                          ]
          )

    -- Sprint 4.85: registering a descriptor adds a mandatory absence read-back
    -- to every surface that projects it, so a descriptor with no production
    -- executor makes that surface's completion structurally unreachable. The
    -- gate is the join between the registry and the interpreter's dispatch.
    it "Sprint 4.85 no registered target lacks an executor on a completing surface" $ do
      Prodbox.CheckCode.registeredTargetExecutorViolations `shouldBe` []

      -- Not vacuous in either direction. One registered descriptor genuinely
      -- has no executor today, so the gate is being asked a real question.
      let unexecutableKeys =
            [ TeardownRegistry.managedResourceKey descriptor
            | TeardownRegistry.SomeManagedResourceDescriptor descriptor <-
                TeardownRegistry.managedResourceRegistry
            , Left _ <-
                [ TeardownExecutor.registeredTargetExecutorFor
                    (TeardownRegistry.managedResourceKey descriptor)
                ]
            ]
      unexecutableKeys `shouldBe` [TeardownModel.AwsEbsProductionRetainedKey]

      -- And it passes for a reason rather than by accident: the retained EBS
      -- family projects onto exactly the two surfaces that mint no completion
      -- evidence, so no run can claim clean completion over its unreachable
      -- read-back.
      let retainedSurfaces =
            [ surface
            | surface <- [minBound .. maxBound]
            , retained <-
                [ TeardownRegistry.RegisteredManagedResource someDescriptor
                | someDescriptor@(TeardownRegistry.SomeManagedResourceDescriptor descriptor) <-
                    TeardownRegistry.managedResourceRegistry
                , TeardownRegistry.managedResourceKey descriptor
                    == TeardownModel.AwsEbsProductionRetainedKey
                ]
            , TeardownRegistry.cleanupSurfaceAllows surface retained
            ]
      retainedSurfaces
        `shouldBe` [ TeardownModel.ExplicitLongLived
                   , TeardownModel.TotalDecommission
                   ]
      map TeardownModel.cleanupSurfaceMintsCompletionEvidence retainedSurfaces
        `shouldBe` [False, False]

      -- The predicate is discriminating: the per-run surfaces do mint, which
      -- is why the same gap would be a violation there.
      map
        TeardownModel.cleanupSurfaceMintsCompletionEvidence
        [TeardownModel.Cascade, TeardownModel.ExplicitPerRun]
        `shouldBe` [True, True]

    -- Sprint 4.85 validation item 10: bidirectional parity across the complete
    -- total-decommission universe. The two implementations of "total
    -- decommission" had never been compared, and the comparison is the finding.
    -- Sprint 4.85: a registered stack coordinate is only meaningful if a
    -- provisioning program declares its Pulumi project. A registered stack with
    -- no program can never be reconciled or destroyed, and its compiled
    -- desired-absence nodes fail for a reason no report distinguishes from live
    -- infrastructure.
    it "Sprint 4.85 every registered stack has a provisioning program on disk" $ do
      repoViolations <-
        Prodbox.CheckCode.checkRegisteredStackProvisioningPrograms "."
      repoViolations `shouldBe` []

      -- The gate reads the `name:` Pulumi itself resolves rather than inferring
      -- from the directory, because the two do not match: pulumi/aws-eks
      -- provisions stack aws-eks-test.
      Prodbox.CheckCode.pulumiProjectNameIn
        "name: prodbox-aws-eks-test\nruntime: yaml\n"
        `shouldBe` Just "prodbox-aws-eks-test"
      Prodbox.CheckCode.pulumiProjectNameIn "runtime: yaml\n" `shouldBe` Nothing

      -- Mutation exercise: the gate is discriminating, not vacuously empty. An
      -- empty pulumi/ tree reports one violation per registered stack.
      withSystemTempDirectory "prodbox-registered-stack-programs" $ \root -> do
        createDirectoryIfMissing True (root </> "pulumi")
        violations <-
          Prodbox.CheckCode.checkRegisteredStackProvisioningPrograms root
        length violations `shouldBe` 3
        violations `shouldSatisfy` any ("prodbox-aws-eks-test" `isInfixOf`)

    -- Sprint 4.85: the per-run stack names and the EKS cluster name are
    -- projections of the typed registry, not independent constants. They were
    -- authored in three modules, and the cluster name is the tag the EBS reaper
    -- filters on and the coordinate controller ownership is derived from.
    it "Sprint 4.85 stack and cluster names project from the typed registry" $ do
      TeardownRegistry.awsEksPulumiStackName `shouldBe` "aws-eks-test"
      TeardownRegistry.awsEksProvisionedClusterName `shouldBe` "aws-eks-test-cluster"
      LiveResidue.awsEksTestStackName `shouldBe` "aws-eks-test"
      LiveResidue.awsEksSubzoneStackName `shouldBe` "aws-eks-subzone"
      LiveResidue.awsTestStackName `shouldBe` "aws-test"
      AwsEks.awsEksCanonicalClusterName `shouldBe` "aws-eks-test-cluster"
      -- The family's ownership tag is built from the EKS stack name, so "the
      -- EKS stack owns this family" is true by construction rather than a claim
      -- the ownership derivation has to discover.
      TeardownRegistry.managedResourceCoordinate TeardownRegistry.awsEbsPerRunTestResource
        `shouldBe` TeardownModel.AwsEbsPerRunFamilyCoordinate
          "prodbox.io/lifecycle"
          "per-run-test"
          ( TeardownModel.clusterOwnershipTagPrefix
              <> TeardownRegistry.awsEksProvisionedClusterName
          )
          TeardownModel.clusterOwnedTagValue

    it "Sprint 4.85 total-decommission program tags agree with both implementations" $ do
      DecommissionProgramTag.decommissionProgramTagParityViolations `shouldBe` []

      -- Not vacuous: both images are measured from real sources and both are
      -- non-empty, so the parity is being asked a real question.
      compiledTags <-
        either
          (\err -> expectationFailure (show err) >> pure [])
          pure
          DecommissionProgramTag.measuredCompiledDecommissionTags
      compiledTags `shouldSatisfy` (not . null)
      DecommissionProgramTag.measuredRunnerDecommissionTags
        `shouldSatisfy` (not . null)

      -- The two universes were disjoint across all twenty-one tags. Sprint
      -- 4.85 has closed four overlaps, each by moving an operation the
      -- compiled program already emitted into the signed receipt graph: the
      -- final no-retention audit (previously an out-of-band tail that ran
      -- after the runner returned), the home-substrate uninstall (previously
      -- run by nothing at all), the operator's retained-local-data disposition
      -- (previously decided by nobody), and the terminal receipt (previously a
      -- convergence fact that existed only in process memory).
      filter
        (`elem` DecommissionProgramTag.measuredRunnerDecommissionTags)
        compiledTags
        `shouldBe` [ DecommissionProgramTag.TotalDecommissionEscapeAuditTag
                   , DecommissionProgramTag.HomeSubstrateUninstallTag
                   , DecommissionProgramTag.LocalDataDispositionTag
                   , DecommissionProgramTag.TerminalReceiptTag
                   ]

      -- Every compiled node carries an operation the semantic universe names;
      -- the unmapped constructors are exactly the ones this surface never
      -- emits, so an untagged compiled node would be a violation above. All
      -- four terminal operations are now two-sided; the remaining one-sided
      -- tags are the registered-target work (compiled-only) and the SES / TLS /
      -- backup / shared-bucket families (runner-only).
      map
        DecommissionProgramTag.decommissionProgramTagImplementation
        compiledTags
        `shouldSatisfy` all
          ( `elem`
              [ DecommissionProgramTag.CompiledProgramOnly
              , DecommissionProgramTag.CompiledProgramAndRunner
              ]
          )
      filter
        ( (== DecommissionProgramTag.CompiledProgramAndRunner)
            . DecommissionProgramTag.decommissionProgramTagImplementation
        )
        [minBound .. maxBound]
        `shouldBe` [ DecommissionProgramTag.TotalDecommissionEscapeAuditTag
                   , DecommissionProgramTag.HomeSubstrateUninstallTag
                   , DecommissionProgramTag.LocalDataDispositionTag
                   , DecommissionProgramTag.TerminalReceiptTag
                   ]

      -- Together the two images cover the whole declared universe, so no tag
      -- is declared that neither side produces. The shared tag appears in
      -- both, so the union rather than the concatenation is the universe.
      sort (nub (compiledTags ++ DecommissionProgramTag.measuredRunnerDecommissionTags))
        `shouldBe` sort [minBound .. maxBound]

    it "Sprint 4.85 the runner's terminal-phase order is the compiled program's" $ do
      -- The signed graph and the compiled TotalDecommission program both state
      -- an order over the same semantic operations, and each simply asserted
      -- one. This is the join: the audit proves what the deletions achieved,
      -- the home uninstall dismantles the plane the earlier nodes were
      -- answered through, and the operator's retained-local-data disposition
      -- follows the uninstall that stopped writing to the root.
      DecommissionProgramTag.decommissionTerminalPhaseOrderViolations
        `shouldBe` []

      -- Not vacuous, and two-sided: the compiled program orders the audit
      -- before the uninstall and does not order the reverse, so an unordered
      -- pair cannot read as ordered.
      DecommissionProgramTag.compiledDecommissionTagPrecedes
        DecommissionProgramTag.TotalDecommissionEscapeAuditTag
        DecommissionProgramTag.HomeSubstrateUninstallTag
        `shouldBe` True
      DecommissionProgramTag.compiledDecommissionTagPrecedes
        DecommissionProgramTag.HomeSubstrateUninstallTag
        DecommissionProgramTag.TotalDecommissionEscapeAuditTag
        `shouldBe` False
      DecommissionProgramTag.compiledDecommissionTagPrecedes
        DecommissionProgramTag.HomeSubstrateUninstallTag
        DecommissionProgramTag.LocalDataDispositionTag
        `shouldBe` True
      DecommissionProgramTag.compiledDecommissionTagPrecedes
        DecommissionProgramTag.LocalDataDispositionTag
        DecommissionProgramTag.HomeSubstrateUninstallTag
        `shouldBe` False
      -- A tag the compiled program never emits precedes nothing, rather than
      -- vacuously preceding everything.
      DecommissionProgramTag.compiledDecommissionTagPrecedes
        DecommissionProgramTag.SharedObjectBucketTag
        DecommissionProgramTag.HomeSubstrateUninstallTag
        `shouldBe` False

    it "Sprint 4.85 the signed interpreter registry is derived from the tag universe" $ do
      -- The interpreter registry identity is digested into VerifierMetadata and
      -- signed into the manifest, so the operator's signature covers which
      -- interpreters the runner was built with. It was a hand-authored list of
      -- ten strings beside a `case` of the same ten, joined to neither each
      -- other nor the node universe: a node implemented with a new interpreter
      -- would have been absent from the signed identity while a manifest naming
      -- it still verified.
      DecommissionProgramTag.decommissionInterpreterIdentityViolations
        `shouldBe` []

      -- Not vacuous: the join is discriminating in both directions. Every tag
      -- the runner implements names an interpreter, and every tag it does not
      -- names none -- so the registry cannot advertise an interpreter no
      -- manifest node reaches.
      [ tag
        | tag <- [minBound .. maxBound]
        , DecommissionProgramTag.decommissionRunnerInterpretsTag tag
        ]
        `shouldBe` DecommissionProgramTag.measuredRunnerDecommissionTags
      map
        DecommissionProgramTag.decommissionRunnerInterpreterIdentity
        DecommissionProgramTag.measuredRunnerDecommissionTags
        `shouldSatisfy` all isJust
      [ DecommissionProgramTag.decommissionRunnerInterpreterIdentity tag
        | tag <- [minBound .. maxBound]
        , not (DecommissionProgramTag.decommissionRunnerInterpretsTag tag)
        ]
        `shouldSatisfy` all isNothing

      -- The derivation is what carried the Sprint-4.85 terminal audit into the
      -- signed identity: the runner gained its first escape-audit interpreter,
      -- so this list and the digest over it genuinely changed, and
      -- 'nukeInterpreterRegistryVersion' was bumped in the same change. It has
      -- since carried the home uninstall and the retained-local-data
      -- disposition the same way, taking the version to 4. A receipt signed
      -- under an earlier version must not verify against this runner.
      DecommissionProgramTag.decommissionRunnerInterpreterRegistry
        `shouldBe` [ "total-decommission-escape-audit-v1"
                   , "home-substrate-uninstall-v1"
                   , "local-data-disposition-v1"
                   , "terminal-receipt-v1"
                   , "ses-consumer-quiescence-v1"
                   , "ses-provider-stack-v1"
                   , "ses-smtp-iam-v1"
                   , "target-generation-v1"
                   , "retained-custody-v1"
                   , "tls-retained-objects-v1"
                   , "tls-retention-identity-v1"
                   , "backup-prefix-absence-proof-v1"
                   , "backup-objects-identity-v1"
                   , "shared-object-bucket-v1"
                   ]
      Nuke.nukeInterpreterRegistryIdentity
        `shouldBe` BS8.unlines
          [ "prodbox-decommission-interpreter-registry-v1"
          , "total-decommission-escape-audit-v1"
          , "home-substrate-uninstall-v1"
          , "local-data-disposition-v1"
          , "terminal-receipt-v1"
          , "ses-consumer-quiescence-v1"
          , "ses-provider-stack-v1"
          , "ses-smtp-iam-v1"
          , "target-generation-v1"
          , "retained-custody-v1"
          , "tls-retained-objects-v1"
          , "tls-retention-identity-v1"
          , "backup-prefix-absence-proof-v1"
          , "backup-objects-identity-v1"
          , "shared-object-bucket-v1"
          ]

    it "Sprint 4.84 the effect-bearing registry agrees with the flat inventory" $ do
      ResourceRegistry.effectRegistryLifecycleClassViolations `shouldBe` []
      -- Not vacuous: the projection covers every statically named entry,
      -- including the three operational identities the registry now owns.
      map fst ResourceRegistry.effectRegistryStaticIdentities
        `shouldBe` [ "aws-eks"
                   , "aws-eks-subzone"
                   , "aws-test"
                   , "public-edge-tls"
                   , "aws-ses"
                   , "legacy-harbor-helm-release"
                   , "operational-aws-ses-lease-role"
                   , "operational-iam-user"
                   , "operational-aws-config"
                   ]

    it "Sprint 4.84 the registry owns every operational field except the effect" $ do
      -- The effect supplier can no longer invent a name or assert a class.
      map ResourceRegistry.operationalResourceName ResourceRegistry.operationalResourceIdentities
        `shouldBe` [ "operational-aws-ses-lease-role"
                   , "operational-iam-user"
                   , "operational-aws-config"
                   ]
      let entries =
            map
              (\identity -> ResourceRegistry.operationalManagedResourceFor identity (const (pure ExitSuccess)))
              ResourceRegistry.operationalResourceIdentities
      map ResourceRegistry.resourceClass entries
        `shouldBe` replicate 3 ResourceClass.Operational
      nub (map ResourceRegistry.resourceDestroyCommand entries)
        `shouldBe` ["prodbox aws teardown"]

    it "Sprint 4.84 enumerates the per-run stacks in documented teardown order" $ do
      -- Dependent VPC/subnet residue must tear down before the broader network
      -- substrate, and the enumeration order is what carries that.
      ResourceRegistry.perRunStackIdentities
        `shouldBe` [ ResourceRegistry.PerRunAwsEks
                   , ResourceRegistry.PerRunAwsEksSubzone
                   , ResourceRegistry.PerRunAwsTest
                   ]
      map
        (ResourceRegistry.resourceName . ResourceRegistry.perRunManagedResourceFor)
        ResourceRegistry.perRunStackIdentities
        `shouldBe` map ResourceRegistry.resourceName ResourceRegistry.perRunManagedResources

    it "all-absent destroys nothing (cascade skips per-run destroys)" $
      presentNames Residue.ResidueAbsent Residue.ResidueAbsent Residue.ResidueAbsent `shouldBe` []

    it "all-present destroys every per-run stack in canonical order" $
      presentNames residueFixturePresent residueFixturePresent residueFixturePresent
        `shouldBe` ["aws-eks", "aws-eks-subzone", "aws-test"]

    it "only-middle-present preserves the canonical ordering position" $
      presentNames Residue.ResidueAbsent residueFixturePresent Residue.ResidueAbsent
        `shouldBe` ["aws-eks-subzone"]

    it "only-eks-present destroys only aws-eks" $
      presentNames residueFixturePresent Residue.ResidueAbsent Residue.ResidueAbsent
        `shouldBe` ["aws-eks"]

    it "only-test-present destroys only aws-test" $
      presentNames Residue.ResidueAbsent Residue.ResidueAbsent residueFixturePresent
        `shouldBe` ["aws-test"]

    it "ResidueUnreachable on any per-run stack is skipped (per-run graceful degradation)" $ do
      let minioDown = Residue.ResidueUnreachable residueFixtureMinioReason
      presentNames minioDown minioDown minioDown `shouldBe` []
      presentNames residueFixturePresent minioDown residueFixturePresent
        `shouldBe` ["aws-eks", "aws-test"]

    it "reconcileAbsent destroys present resources in order and stops fast on failure" $ do
      destroyed <- newIORef ([] :: [String])
      let pairs =
            [ (registryFixtureResource "first" ExitSuccess destroyed, residueFixturePresent)
            , (registryFixtureResource "skipped-absent" ExitSuccess destroyed, Residue.ResidueAbsent)
            , (registryFixtureResource "boom" (ExitFailure 1) destroyed, residueFixturePresent)
            , (registryFixtureResource "after-failure" ExitSuccess destroyed, residueFixturePresent)
            ]
      outcome <- ResourceRegistry.reconcileAbsent "/tmp" pairs
      ResourceRegistry.absentReconcileDestroyExit outcome `shouldBe` ExitFailure 1
      ResourceRegistry.absentReconcileExitCode outcome `shouldBe` ExitFailure 1
      readIORef destroyed `shouldReturn` ["first", "boom"]

  describe "Sprint 4.76 reconcileAbsent separates observed-absent from unobserved" $ do
    let minioDown = Residue.ResidueUnreachable residueFixtureMinioReason

    it "resourcesObservedAbsent and resourcesUnobserved partition the skipped set" $ do
      let pairs =
            ResourceRegistry.pairPerRunResidue
              ResourceRegistry.PerRunResidueAnswers
                { ResourceRegistry.perRunAnswerAwsEks = Residue.ResidueAbsent
                , ResourceRegistry.perRunAnswerAwsEksSubzone = minioDown
                , ResourceRegistry.perRunAnswerAwsTest = residueFixturePresent
                }
      map ResourceRegistry.resourceName (ResourceRegistry.resourcesObservedAbsent pairs)
        `shouldBe` ["aws-eks"]
      map ResourceRegistry.resourceName (ResourceRegistry.resourcesUnobserved pairs)
        `shouldBe` ["aws-eks-subzone"]
      map ResourceRegistry.resourceName (ResourceRegistry.resourcesToDestroy pairs)
        `shouldBe` ["aws-test"]

    it "an all-absent reconcile succeeds and reports no unobserved resource" $ do
      destroyed <- newIORef ([] :: [String])
      let pairs =
            [ (registryFixtureResource "eks" ExitSuccess destroyed, Residue.ResidueAbsent)
            , (registryFixtureResource "test" ExitSuccess destroyed, Residue.ResidueAbsent)
            ]
      outcome <- ResourceRegistry.reconcileAbsent "/tmp" pairs
      ResourceRegistry.absentReconcileObservedAbsent outcome `shouldBe` ["eks", "test"]
      ResourceRegistry.absentReconcileUnobserved outcome `shouldBe` []
      ResourceRegistry.absentReconcileExitCode outcome `shouldBe` ExitSuccess
      readIORef destroyed `shouldReturn` []

    it "an all-unobserved reconcile runs no destroy and CANNOT report success" $ do
      -- The reproduction: before Sprint 4.76 this input and the all-absent
      -- input above produced the same ExitSuccess and the same
      -- "no live per-run residue" line.
      destroyed <- newIORef ([] :: [String])
      let pairs =
            [ (registryFixtureResource "eks" ExitSuccess destroyed, minioDown)
            , (registryFixtureResource "test" ExitSuccess destroyed, minioDown)
            ]
      outcome <- ResourceRegistry.reconcileAbsent "/tmp" pairs
      ResourceRegistry.absentReconcileObservedAbsent outcome `shouldBe` []
      ResourceRegistry.absentReconcileUnobserved outcome `shouldBe` ["eks", "test"]
      -- The destroy fold itself is clean; the reconcile is not.
      ResourceRegistry.absentReconcileDestroyExit outcome `shouldBe` ExitSuccess
      ResourceRegistry.absentReconcileExitCode outcome `shouldBe` ExitFailure 1
      readIORef destroyed `shouldReturn` []

    it "a successful destroy does not absolve a sibling that was never observed" $ do
      destroyed <- newIORef ([] :: [String])
      let pairs =
            [ (registryFixtureResource "eks" ExitSuccess destroyed, residueFixturePresent)
            , (registryFixtureResource "test" ExitSuccess destroyed, minioDown)
            ]
      outcome <- ResourceRegistry.reconcileAbsent "/tmp" pairs
      ResourceRegistry.absentReconcileDestroyExit outcome `shouldBe` ExitSuccess
      ResourceRegistry.absentReconcileExitCode outcome `shouldBe` ExitFailure 1
      readIORef destroyed `shouldReturn` ["eks"]

    it "the scope label is derived from the registry entries' own lifecycle class" $ do
      destroyed <- newIORef ([] :: [String])
      let perRun = registryFixtureResource "eks" ExitSuccess destroyed
          operational =
            (registryFixtureResource "operational-iam-user" ExitSuccess destroyed)
              { ResourceRegistry.resourceClass = ResourceClass.Operational
              }
      ResourceRegistry.reconcileScopeLabel [(perRun, Residue.ResidueAbsent)]
        `shouldBe` "Per-run"
      ResourceRegistry.reconcileScopeLabel [(operational, Residue.ResidueAbsent)]
        `shouldBe` "Operational"
      ResourceRegistry.reconcileScopeLabel
        [(perRun, Residue.ResidueAbsent), (operational, Residue.ResidueAbsent)]
        `shouldBe` "Managed"

  describe "Sprint 4.26 destructive commands route through runPlanWithOptions" $ do
    let defaultFlags =
          Rke2DeleteFlags
            { rke2DeleteYes = True
            , rke2DeleteCascade = False
            }
        cascadeFlags = defaultFlags {rke2DeleteCascade = True}

    it "default-delete plan is a pure local uninstall (no per-run AWS backend interaction)" $ do
      let rendered = renderNativeDeletePlan "/repo" defaultFlags
      rendered `shouldContain` "MODE=default"
      rendered `shouldContain` "STEP=delete_rke2_cluster_substrate"
      rendered `shouldContain` "STEP=render_retained_state_notice"
      -- The default delete no longer queries/gates/destroys the per-run
      -- AWS Pulumi backend; that lives in --cascade only.
      rendered `shouldNotContain` "STEP=per_run_destroy"
      rendered `shouldNotContain` "STEP=refuse_on_live_per_run_residue"
      rendered `shouldNotContain` "ALLOW_PULUMI_RESIDUE"

    it "cascade plan renders the canonical drain-before-destroys narration + every per-run stack" $ do
      let rendered = renderNativeDeletePlan "/repo" cascadeFlags
      rendered `shouldContain` cascadeOrderNarration
      rendered `shouldContain` "STEP=k8s_drain"
      rendered `shouldContain` "STEP=per_run_destroy aws-eks-subzone"
      -- drain step precedes the per-run destroy steps in the rendered plan.
      let planLines = lines rendered
          drainIdx = elemIndex "STEP=k8s_drain" planLines
          destroyIdx = elemIndex "STEP=per_run_destroy aws-eks" planLines
      (drainIdx < destroyIdx) `shouldBe` True
      drainIdx `shouldSatisfy` (/= Nothing)

    it "the cascade per-run sweep lists exactly the per-run Pulumi stack resources in order" $ do
      let registryNames =
            map ResourceRegistry.resourceName ResourceRegistry.perRunManagedResources
          planSteps =
            [ drop (length ("STEP=per_run_destroy " :: String)) line
            | line <- lines (renderNativeDeletePlan "/repo" cascadeFlags)
            , "STEP=per_run_destroy " `isPrefixOf` line
            ]
      planSteps `shouldBe` registryNames
      registryNames `shouldBe` StackDescriptor.perRunStackDescriptorNames

    it "rke2 delete --dry-run renders the plan and performs NO mutation (the core 4.26 fix)" $ do
      -- The audit's #1 bug: `rke2 delete --yes --dry-run` SILENTLY MUTATED.
      -- runPlanWithOptions with dryRun=True must render the destructive plan
      -- and NEVER invoke the apply closure.
      applyCalled <- newIORef False
      let plan = buildNativeDeletePlan "/repo" defaultFlags
      exit <-
        runPlanWithOptions
          PlanOptions {dryRun = True, planFile = Nothing}
          plan
          (\_ -> writeIORef applyCalled True >> pure (ExitFailure 99))
      exit `shouldBe` ExitSuccess
      mutated <- readIORef applyCalled
      mutated `shouldBe` False

    it "rke2 delete --plan-file writes the rendered destructive plan" $ do
      applyCalled <- newIORef False
      tmpDir <- getTemporaryDirectory
      let planPath = tmpDir </> "prodbox-4-26-rke2-delete-plan.txt"
          plan = buildNativeDeletePlan "/repo" cascadeFlags
      _ <-
        runPlanWithOptions
          PlanOptions {dryRun = True, planFile = Just planPath}
          plan
          (\_ -> writeIORef applyCalled True >> pure ExitSuccess)
      written <- readFile planPath
      written `shouldContain` cascadeOrderNarration
      written `shouldContain` "STEP=per_run_destroy aws-eks-subzone"
      readIORef applyCalled `shouldReturn` False

    it "nuke --dry-run renders the authenticated receipt plan and does not prompt" $ do
      let plan = Nuke.renderNukePlan "/repo"
      plan `shouldContain` "PROTOCOL=signed-external-decommission-v1"
      plan `shouldContain` "RECEIPT=durable intent before every effect"
      plan `shouldContain` "NODE=total-decommission-escape-audit"
      plan `shouldContain` "NODE=home-substrate-uninstall"
      plan `shouldContain` "NODE=local-data-disposition (<required-for-apply>)"
      plan `shouldContain` "NODE=terminal-receipt (unique terminal)"

  -- Sprint 5.6: the three destructive `--dry-run` goldens (audit V80 found
  -- them missing). Each golden pins the exact planned step list a
  -- destructive path emits WITHOUT executing it (the goldens render the
  -- pure plan renderer, which `rke2 delete --dry-run` / `nuke --dry-run`
  -- route through via runPlanWithOptions; the separate Sprint 4.26 tests
  -- above prove dry-run performs NO mutation). The per-run / long-lived
  -- stack lines are registry-derived, so the golden tracks the
  -- managed-resource registry / StackDescriptor SSoT, and the drift check
  -- below fails if a registered resource is added without updating the
  -- golden.
  describe "Sprint 5.6 destructive dry-run goldens (registry-generated)" $ do
    let destructiveGoldenRepoRoot = "/tmp/prodbox"
        defaultDeleteFlags =
          Rke2DeleteFlags
            { rke2DeleteYes = True
            , rke2DeleteCascade = False
            }
        cascadeDeleteFlags = defaultDeleteFlags {rke2DeleteCascade = True}

    let renderUtf8 = BL.fromStrict . TextEncoding.encodeUtf8 . Text.pack

    goldenTest
      "rke2 delete --dry-run plan"
      "test/golden/destructive/rke2-delete.txt"
      ( pure
          (renderUtf8 (renderNativeDeletePlan destructiveGoldenRepoRoot defaultDeleteFlags))
      )

    goldenTest
      "rke2 delete --cascade --dry-run plan"
      "test/golden/destructive/rke2-delete-cascade.txt"
      ( pure
          (renderUtf8 (renderNativeDeletePlan destructiveGoldenRepoRoot cascadeDeleteFlags))
      )

    goldenTest
      "nuke --dry-run plan"
      "test/golden/destructive/nuke.txt"
      (pure (renderUtf8 (Nuke.renderNukePlan destructiveGoldenRepoRoot)))

    it "the cascade rke2-delete golden names every PerRun registry resource (drift guard)" $ do
      defaultGolden <- readFile "test/golden/destructive/rke2-delete.txt"
      cascadeGolden <- readFile "test/golden/destructive/rke2-delete-cascade.txt"
      let perRunNames = map ResourceRegistry.resourceName ResourceRegistry.perRunManagedResources
      -- The default delete is a pure local uninstall: it has NO per_run_destroy
      -- steps. Only the cascade golden carries the per-run sweep; if a new
      -- PerRun resource is registered without regenerating the cascade golden,
      -- this fails.
      defaultGolden `shouldNotContain` "STEP=per_run_destroy"
      mapM_
        (\name -> cascadeGolden `shouldContain` ("STEP=per_run_destroy " ++ name))
        perRunNames
      perRunNames `shouldBe` StackDescriptor.perRunStackDescriptorNames

    it "the nuke golden pins the authenticated external protocol and closed node families" $ do
      nukeGolden <- readFile "test/golden/destructive/nuke.txt"
      nukeGolden `shouldContain` "PROTOCOL=signed-external-decommission-v1"
      nukeGolden `shouldContain` "NODE=ses-consumer-quiescence"
      nukeGolden
        `shouldContain` "NODE=target-generation-tombstone (one per signed manifest target)"
      nukeGolden `shouldContain` "NODE=total-decommission-escape-audit"
      -- Sprint 4.85: the home uninstall is no longer the terminal node -- the
      -- operator's retained-local-data disposition follows it -- and the
      -- terminal note moved with the derived order rather than being edited.
      nukeGolden `shouldContain` "NODE=home-substrate-uninstall\n"
      nukeGolden `shouldNotContain` "STEP=1 prodbox aws stack aws-ses destroy"
      -- Sprint 4.85: `--dry-run` renders the plan with no operator decision
      -- supplied, and the disposition node says so rather than showing a
      -- default. A default would make the artifact that authorizes the run
      -- assert a decision nobody made.
      nukeGolden `shouldContain` "LOCAL_DATA=<required-for-apply>"
      nukeGolden `shouldContain` "NODE=local-data-disposition (<required-for-apply>)\n"
      -- The terminal note moved again, to the node the derived order now ends
      -- with. It is derived, so the plan followed without being edited.
      nukeGolden `shouldContain` "NODE=terminal-receipt (unique terminal)"
      -- Sprint 4.85: the plan's node lines are derived from the inventory the
      -- Authority signs, so a node added to that inventory reaches the artifact
      -- the operator approves. Previously they were a sixth authored copy of
      -- the node universe and a node could be destroyed without appearing here.
      mapM_ (shouldContain nukeGolden) (Nuke.nukePlanNodeLines Nothing)
      length (Nuke.nukePlanNodeLines Nothing) `shouldBe` 14
      -- The rendered decision is the operator's, not a constant.
      Nuke.nukePlanNodeLines (Just Manifest.DeleteLocalData)
        `shouldContain` ["NODE=local-data-disposition (delete)"]
      Nuke.nukePlanNodeLines (Just Manifest.RetainLocalData)
        `shouldContain` ["NODE=local-data-disposition (retain)"]

  describe "Sprint 4.26 checkPlanOptionsHonored lint" $ do
    it "fires when Rke2Delete binds its PlanOptions to a _ wildcard" $ do
      let offending = "    Rke2Delete flags _planOptions ->\n      foo\n"
      planOptionsHonoredViolations "src/Prodbox/CLI/Rke2.hs" offending
        `shouldSatisfy` (not . null)

    it "fires when NativeNuke binds its NukeOptions to a _ wildcard" $ do
      let offending = "    NativeNuke _opts -> runNukeCommand repoRoot defaultNukeOptions\n"
      planOptionsHonoredViolations "src/Prodbox/Native.hs" offending
        `shouldSatisfy` (not . null)

    it "is silent when the options field is bound to a real name" $ do
      let honest =
            "    Rke2Delete flags planOptions ->\n"
              ++ "      runPlanWithOptions planOptions plan apply\n"
              ++ "    NativeNuke nukeOptions -> runNukeCommand repoRoot nukeOptions\n"
      planOptionsHonoredViolations "src/Prodbox/CLI/Rke2.hs" honest `shouldBe` []

    it "the live Rke2.hs / Nuke.hs / Native.hs dispatch arms are clean" $ do
      rke2Source <- readFile "src/Prodbox/CLI/Rke2.hs"
      nativeSource <- readFile "src/Prodbox/Native.hs"
      planOptionsHonoredViolations "src/Prodbox/CLI/Rke2.hs" rke2Source `shouldBe` []
      planOptionsHonoredViolations "src/Prodbox/Native.hs" nativeSource `shouldBe` []

    it "Sprint 0.28: covers every destructive arm, not just the original two" $ do
      -- Standard C. This case pinned the table to exactly `["Rke2Delete",
      -- "NativeNuke"]`, which made the two-constructor region an asserted
      -- invariant while seven destructive `PlanOptions`-carrying constructors
      -- dispatched outside it.
      take 2 (map fst destructivePlanOptionsArms) `shouldBe` ["Rke2Delete", "NativeNuke"]
      length destructivePlanOptionsArms `shouldBe` 9

    it "Sprint 0.28: the projection exemption is a (path, constructor) pair" $ do
      -- A bare constructor exemption would also excuse the real dispatch site
      -- in src/Prodbox/Aws.hs, which is inside the region and binds properly.
      map (\(path, name, _) -> (path, name)) planOptionsProjectionExemptions
        `shouldBe` [("src/Prodbox/Native.hs", "AwsTeardown")]
      awsSource <- readFile "src/Prodbox/Aws.hs"
      planOptionsHonoredViolations "src/Prodbox/Aws.hs" awsSource `shouldBe` []

