          `shouldBe` 5

    describe "Sprint 0.27 Standard-H sprint field gate" $ do
      let block heading fields = unlines (("## Sprint " ++ heading) : fields ++ ["", "### Objective", "body"])

      it "splits a plan document into sprint blocks" $
        map
          fst
          (planSprintBlocks (block "1.1: A" ["**Status**: Done"] ++ block "1.2: B" ["**Status**: Done"]))
          `shouldBe` ["## Sprint 1.1: A", "## Sprint 1.2: B"]

      it "reports both fields missing when a block carries neither" $
        sprintBlockMissingFields (block "1.1: A" ["**Status**: Done"])
          `shouldBe` ["Implementation", "Docs"]

      it "accepts the plain heading form" $
        sprintBlockMissingFields
          (block "1.1: A" ["**Implementation**: `src/X.hs`", "**Docs to update**: `d.md`"])
          `shouldBe` []

      it "accepts a qualifier after the closing bold, as Sprint 1.62 writes it" $
        -- `**Implementation** (landed): …` names its paths. A stricter rule
        -- would report a formatting difference as missing evidence, which is
        -- how the ledger row this gate closes came to overcount.
        sprintBlockMissingFields
          (block "1.62: A" ["**Implementation** (landed): `src/X.hs`", "**Docs updated**: none."])
          `shouldBe` []

      it "accepts a qualifier inside the bold, as the Phase-7 increments write it" $
        sprintBlockMissingFields
          ( block
              "4.50: A"
              [ "**Implementation (Increment A, 2026-07-26)**: `src/X.hs`"
              , "**Docs to update**: `d.md`"
              ]
          )
          `shouldBe` []

      it "rejects a heading that never closes its bold or reaches a colon" $ do
        sprintBlockMissingFields (block "1.1: A" ["**Implementation `src/X.hs`", "**Docs**: d"])
          `shouldBe` ["Implementation"]
        sprintBlockMissingFields (block "1.1: A" ["**Implementation** `src/X.hs`", "**Docs**: d"])
          `shouldBe` ["Implementation"]

      it "does not accept a field mentioned only inside a fenced block" $
        sprintBlockMissingFields
          ( block
              "1.1: A"
              ["**Docs**: d", "```markdown", "**Implementation**: `src/X.hs`", "```"]
          )
          `shouldBe` ["Implementation"]

      it "does not confuse a prose line that merely starts with bold" $
        sprintBlockMissingFields
          (block "1.1: A" ["**Implementation notes are below**: see § 2", "**Docs**: d"])
          `shouldBe` []

    describe "development-plan Resume Here projection" $ do
      let resumeHeader =
            [ "| Order | Sprint | Phase | State | Dependency |"
            , "|-------|--------|-------|-------|------------|"
            ]
          activeRow = "| 1 | `3.41` | 3 | Next | — |"
          phaseDocument phaseNumber sprintId statusText =
            ( "DEVELOPMENT_PLAN/phase-" ++ phaseNumber ++ "-fixture.md"
            , unlines
                [ "# Phase " ++ phaseNumber
                , ""
                , "## Sprint " ++ sprintId ++ ": Fixture"
                , ""
                , "**Status**: " ++ statusText
                , "**Implementation**: `src/Fixture.hs`"
                , "**Docs to update**: `DEVELOPMENT_PLAN/README.md`"
                ]
            )
          fixture statusText rows owner =
            [
              ( "DEVELOPMENT_PLAN/README.md"
              , unlines (["# Plan", "", "## Resume Here", ""] ++ resumeHeader ++ rows)
              )
            , ("DEVELOPMENT_PLAN/00-overview.md", "# Static overview\n")
            ,
              ( "DEVELOPMENT_PLAN/legacy-tracking-for-deletion.md"
              , unlines
                  [ "# Legacy"
                  , ""
                  , "## Pending Removal"
                  , ""
                  , "| Item | Owning Sprint | Notes |"
                  , "|------|---------------|-------|"
                  , "| Fixture debt | " ++ owner ++ " | Remove it. |"
                  , ""
                  , "## Pending Removal Notes"
                  ]
              )
            , phaseDocument "3" "3.41" statusText
            ]
          replaceDocument path replacement =
            map
              ( \(candidatePath, contents) ->
                  if candidatePath == path
                    then (candidatePath, replacement)
                    else (candidatePath, contents)
              )
          hasViolation needle = any (needle `isInfixOf`) . developmentPlanResumeViolations

      it "accepts an exact Active numerical queue" $
        developmentPlanResumeViolations (fixture "Active" [activeRow] "Sprint `3.41`")
          `shouldBe` []

      it "classifies status by its leading token rather than later Done prose" $
        developmentPlanResumeViolations
          (fixture "Active (Done criteria remain open)." [activeRow] "Sprint `3.41`")
          `shouldBe` []

      it "allows the first Planned sprint to be Next" $
        developmentPlanResumeViolations (fixture "Planned" [activeRow] "Sprint `3.41`")
          `shouldBe` []

      it "requires every Blocked row to name an earlier queue dependency" $ do
        let documents =
              fixture
                "Active"
                [activeRow, "| 2 | `4.84` | 4 | Blocked | — |"]
                "Sprint `3.41`"
                ++ [phaseDocument "4" "4.84" "Blocked"]
        documents `shouldSatisfy` hasViolation "Blocked but names no earlier dependency"

      it "rejects prose and duplicate ids in the dependency cell" $ do
        let phaseFour = phaseDocument "4" "4.84" "Active"
            proseDocuments =
              fixture
                "Active"
                [activeRow, "| 2 | `4.84` | 4 | Parked | `3.41`, prose |"]
                "Sprint `3.41`"
                ++ [phaseFour]
            duplicateDocuments =
              fixture
                "Active"
                [activeRow, "| 2 | `4.84` | 4 | Parked | `3.41`, `3.41` |"]
                "Sprint `3.41`"
                ++ [phaseFour]
        proseDocuments `shouldSatisfy` hasViolation "must spell dependencies exactly"
        duplicateDocuments `shouldSatisfy` hasViolation "repeats dependency `3.41`"

      it "rejects a missing Pending Removal table and a nonexistent owner" $ do
        let baseDocuments = fixture "Active" [activeRow] "Sprint `3.41`"
            noTableDocuments =
              replaceDocument
                "DEVELOPMENT_PLAN/legacy-tracking-for-deletion.md"
                "# Legacy\n\n## Pending Removal\n\nNo table.\n"
                baseDocuments
            phantomOwnerDocuments = fixture "Active" [activeRow] "Sprint `9.99`"
        noTableDocuments `shouldSatisfy` hasViolation "must contain the table"
        phantomOwnerDocuments `shouldSatisfy` hasViolation "nonexistent Sprint `9.99`"

      it "accepts an explicitly Unowned Pending Removal row" $
        developmentPlanResumeViolations
          (fixture "Active" [activeRow] "**Unowned** — no canonical owner")
          `shouldBe` []

      it "ignores Resume and Sprint examples inside fenced Markdown" $ do
        let fencedDocuments =
              map
                ( \(path, contents) ->
                    if path == "DEVELOPMENT_PLAN/README.md"
                      then
                        ( path
                        , contents
                            ++ "\n```markdown\n## Resume Here\n| fake |\n```\n"
                        )
                      else
                        if "DEVELOPMENT_PLAN/phase-" `isPrefixOf` path
                          then
                            ( path
                            , contents
                                ++ "\n```markdown\n## Sprint 9.99: Fake\n**Status**: Active\n```\n"
                            )
                          else (path, contents)
                )
                (fixture "Active" [activeRow] "Sprint `3.41`")
        developmentPlanResumeViolations fencedDocuments `shouldBe` []

      it "rejects duplicate real sprint identifiers across phase files" $ do
        let documents =
              fixture "Active" [activeRow] "Sprint `3.41`"
                ++ [phaseDocument "3" "3.41" "Done"]
        documents `shouldSatisfy` hasViolation "declared more than once"

      it "accepts the complete current DEVELOPMENT_PLAN projection" $ do
        repoRoot <- getCurrentDirectory
        repoPaths <- listRepoOwnedPaths repoRoot
        let planPaths =
              [ path
              | path <- repoPaths
              , "DEVELOPMENT_PLAN/" `isPrefixOf` path
              , ".md" `isSuffixOf` path
              ]
        planDocuments <-
          mapM
            ( \relativePath -> do
                contents <- readFile' (repoRoot </> relativePath)
                pure (relativePath, contents)
            )
            planPaths
        developmentPlanResumeViolations planDocuments `shouldBe` []

    describe "Sprint 0.22 headingSectionNumber / documentSectionNumbers" $ do
      it "reads a plain numbered heading" $
        headingSectionNumber "## 7. Testing Implications" `shouldBe` Just "7"

      it "reads a dotted sub-heading" $
        headingSectionNumber "### 3.1 The managed-resource registry" `shouldBe` Just "3.1"

      it "reads a letter-suffixed heading" $
        headingSectionNumber "## 2C. Enforcement Rings" `shouldBe` Just "2C"

      it "ignores an unnumbered heading" $
        headingSectionNumber "## Cross-References" `shouldBe` Nothing

      it "ignores prose that merely starts with a digit" $
        headingSectionNumber "7. not a heading" `shouldBe` Nothing

      it "collects a document's section numbers outside fenced blocks" $
        documentSectionNumbers
          (unlines ["## 1. A", "```", "## 9. Fenced", "```", "### 1.2 B"])
          `shouldBe` ["1", "1.2"]

    describe "Sprint 0.22 boundSectionCitationsInLine" $ do
      it "binds a citation to an adjacent document name" $
        boundSectionCitationsInLine "see config_doctrine.md \167 7 for detail"
          `shouldBe` [("config_doctrine.md", "7")]

      it "binds inside a markdown link label" $
        boundSectionCitationsInLine "[config_doctrine.md \167 1a](./config_doctrine.md)"
          `shouldBe` [("config_doctrine.md", "1a")]

      it "leaves a bare citation unbound, because the document is ambiguous" $
        boundSectionCitationsInLine "and \167 3B's contract applies" `shouldBe` []

      it "rejects an external-standard citation" $
        boundSectionCitationsInLine "pulsar_messaging_doctrine.md RFC 8949 \167 4.2"
          `shouldBe` []

      it "rejects a line-number-style reference" $
        boundSectionCitationsInLine "doctrine.md \167 1834" `shouldBe` []

      it "refuses to bind across a semicolon" $
        boundSectionCitationsInLine "[README.md](./README.md); \167 4.1 is retained"
          `shouldBe` []

    describe "Sprint 0.24 Tier-0 sibling drift gate" $ do
      -- The gate compares the generator's canonical rendering of the record a
      -- file decodes to against the bytes on disk. These cases pin the pure
      -- core; absence is exercised by the IO wrapper, which never reaches here.
      let generated =
            unlines
              [ "{ parameters ="
              , "  { route53.zone_id = \"\""
              , "  , domain ="
              , "    { demo_fqdn = \"test.resolvefintech.com\""
              , "    , demo_ttl = 60"
              , "    }"
              , "  }"
              , "}"
              ]

      it "an unchanged generated config is silent" $
        tier0DriftFindings ".build/prodbox.dhall" generated generated `shouldBe` []

      it "names the drifted field, not a whole-file diff" $ do
        let handEdited =
              unlines
                [ "{ parameters ="
                , "  { route53.zone_id = \"\""
                , "  , domain ="
                , "    { demo_fqdn = \"test.resolvefintech.com\""
                , "    , demo_ttl = 900"
                , "    }"
                , "  }"
                , "}"
                ]
        tier0DriftLocation generated handEdited
          `shouldBe` "line 5, field `parameters.domain.demo_ttl`"
        case tier0DriftFindings ".build/prodbox.dhall" generated handEdited of
          [finding] -> do
            finding `shouldSatisfy` (".build/prodbox.dhall" `isPrefixOf`)
            finding `shouldSatisfy` ("parameters.domain.demo_ttl" `isInfixOf`)
            finding `shouldSatisfy` ("prodbox config generate" `isInfixOf`)
          findings -> expectationFailure ("expected exactly one finding: " ++ show findings)

      it "recovers the dotted single-field shorthand as one name" $
        tier0DriftLocation
          generated
          ( unlines
              [ "{ parameters ="
              , "  { route53.zone_id = \"Z0HANDEDITED\""
              , "  , domain ="
              , "    { demo_fqdn = \"test.resolvefintech.com\""
              , "    , demo_ttl = 60"
              , "    }"
              , "  }"
              , "}"
              ]
          )
          `shouldBe` "line 2, field `parameters.route53.zone_id`"

      it "closes an enclosing field when a sibling opens at the same column" $
        -- `domain` must not still be on the stack once `capacity` opens beside
        -- it; the indentation-keyed pop is what makes the reported path exact.
        tier0DriftLocation
          ( unlines
              [ "{ parameters ="
              , "  { domain = { demo_ttl = 60 }"
              , "  , capacity ="
              , "    { host_capacity = 1"
              , "    }"
              , "  }"
              , "}"
              ]
          )
          ( unlines
              [ "{ parameters ="
              , "  { domain = { demo_ttl = 60 }"
              , "  , capacity ="
              , "    { host_capacity = 2"
              , "    }"
              , "  }"
              , "}"
              ]
          )
          `shouldBe` "line 4, field `parameters.capacity.host_capacity`"

      it "reports a truncated file at the line where it runs out" $
        tier0DriftLocation generated (unlines ["{ parameters ="])
          `shouldBe` "line 2, field `parameters.route53.zone_id`"

      it "reports an appended trailing line" $
        tier0DriftLocation generated (generated ++ "-- hand-added\n")
          `shouldBe` "line 9"

      it "a type annotation and a `let` binding never enter the field path" $
        -- The Ring-1 preamble the generator prepends is full of both; neither is
        -- a field of the record, so neither may be named as one.
        tier0DriftLocation
          (unlines ["let RV", "    : Type", "    = { milli_cpu : Natural }", "in  1"])
          (unlines ["let RV", "    : Type", "    = { milli_cpu : Natural }", "in  2"])
          `shouldBe` "line 4"

      it "the malformed finding is distinct from a drift finding" $ do
        let finding = tier0MalformedFinding ".build/prodbox.dhall" "unbound variable `x`"
        finding `shouldSatisfy` ("does not decode as a Tier-0 record" `isInfixOf`)
        finding `shouldSatisfy` ("unbound variable `x`" `isInfixOf`)
        finding `shouldSatisfy` ("prodbox config generate" `isInfixOf`)
        finding `shouldSatisfy` (not . ("drifted" `isInfixOf`))

    describe "generatedSectionsReconcilerViolations" $ do
      it "agrees: registered + declared + marked yields no violations" $
        generatedSectionsReconcilerViolations
          "documents/cli/commands.md"
          ["command-registry.markdown"]
          ["command-registry.markdown"]
          ["command-registry.markdown"]
          ["command-registry.markdown", "resource-lifecycle-classes"]
          `shouldBe` []

      it "agrees: a clean `none` doc with no markers and no registry entry" $
        generatedSectionsReconcilerViolations "documents/x.md" [] [] [] ["command-registry.markdown"]
          `shouldBe` []

      it "flags a registry key that the metadata does not declare" $ do
        -- declared=[] while the key is both registered AND physically
        -- marked surfaces two distinct legs: the registry-undeclared leg
        -- (`does not declare`) and the marker-undeclared leg (`but does
        -- not declare`). Both are correct: metadata must declare the key.
        let violations =
              generatedSectionsReconcilerViolations
                "documents/cli/commands.md"
                []
                ["command-registry.markdown"]
                ["command-registry.markdown"]
                ["command-registry.markdown"]
        length violations `shouldBe` 2
        any (isInfixOf "does not declare") violations `shouldBe` True

      it "flags a registry key whose markers are missing from the file" $ do
        let violations =
              generatedSectionsReconcilerViolations
                "documents/cli/commands.md"
                ["command-registry.markdown"]
                []
                ["command-registry.markdown"]
                ["command-registry.markdown"]
        assertExactlyOne violations $ \violation ->
          violation `shouldContain` "are not present in the file"

      it "flags a declared key that no GeneratedSectionRule registers" $ do
        let violations =
              generatedSectionsReconcilerViolations
                "documents/x.md"
                ["ghost-key"]
                []
                []
                ["command-registry.markdown"]
        assertExactlyOne violations $ \violation ->
          violation `shouldContain` "no `GeneratedSectionRule` registers it"

      it "flags a marker present in the file but absent from metadata" $ do
        let violations =
              generatedSectionsReconcilerViolations
                "documents/x.md"
                []
                ["route-registry"]
                []
                ["route-registry"]
        assertExactlyOne violations $ \violation ->
          violation `shouldContain` "but does not declare"

    describe "extractMarkdownLinkTargets" $ do
      it "extracts a relative link target" $
        extractMarkdownLinkTargets "see [the doc](./engineering/code_quality.md#x) please"
          `shouldBe` ["./engineering/code_quality.md#x"]

      it "skips link examples quoted inside inline code spans" $
        extractMarkdownLinkTargets "the `[text](path#anchor)` form is documentation"
          `shouldBe` []

      it "skips link examples inside fenced code blocks" $
        extractMarkdownLinkTargets (unlines ["```", "[x](./gone.md)", "```"])
          `shouldBe` []

      it "extracts multiple targets on one line" $
        extractMarkdownLinkTargets "[a](a.md) and [b](b.md)"
          `shouldBe` ["a.md", "b.md"]

    describe "isRelativeLinkTarget" $ do
      it "treats a relative path as relative" $
        isRelativeLinkTarget "../substrates.md#anchor" `shouldBe` True

      it "skips https URLs" $
        isRelativeLinkTarget "https://example.com" `shouldBe` False

      it "skips mailto links" $
        isRelativeLinkTarget "mailto:matthewnowak@gmail.com" `shouldBe` False

      it "skips pure-anchor links" $
        isRelativeLinkTarget "#section" `shouldBe` False

    describe "relativeLinkResolves" $ do
      it "resolves a sibling link against the doc directory and strips the anchor" $
        relativeLinkResolves
          "DEVELOPMENT_PLAN/phase-8-email-invite-auth.md"
          "substrates.md#cross-substrate-shared-resources"
          `shouldBe` Just "DEVELOPMENT_PLAN/substrates.md"

      it "resolves a parent-relative link normally (the corrected phase-8 link)" $
        relativeLinkResolves
          "DEVELOPMENT_PLAN/phase-8-email-invite-auth.md"
          "../documents/engineering/aws_integration_environment_doctrine.md"
          `shouldBe` Just "documents/engineering/aws_integration_environment_doctrine.md"

      it "shows why the OLD `../substrates.md` link was broken from DEVELOPMENT_PLAN/" $
        relativeLinkResolves
          "DEVELOPMENT_PLAN/phase-8-email-invite-auth.md"
          "../substrates.md"
          `shouldBe` Just "substrates.md"

      it "returns Nothing for an absolute URL" $
        relativeLinkResolves "documents/x.md" "https://example.com" `shouldBe` Nothing

      it "returns Nothing for a pure-anchor link" $
        relativeLinkResolves "documents/x.md" "#section" `shouldBe` Nothing

  describe "Sprint 4.15 cascade decision from drain result" $ do
    it "DrainSucceeded maps to CascadeContinue Nothing" $
      cascadeDecisionFromDrainResult DrainSucceeded `shouldBe` CascadeContinue Nothing

    it "DrainSkipped maps to CascadeContinue (Just reason)" $
      cascadeDecisionFromDrainResult (DrainSkipped "no cluster")
        `shouldBe` CascadeContinue (Just "no cluster")

    it "DrainTimedOut maps to CascadeAbort with surviving resources listed" $ do
      let result = cascadeDecisionFromDrainResult (DrainTimedOut ["Service/foo", "Ingress/bar"])
      case result of
        CascadeAbort reason -> do
          reason `shouldContain` "timed out"
          reason `shouldContain` "Service/foo"
          reason `shouldContain` "Ingress/bar"
        _ -> expectationFailure ("expected CascadeAbort, got: " ++ show result)

    it "DrainFailed maps to CascadeAbort with the error" $ do
      let result = cascadeDecisionFromDrainResult (DrainFailed "kubectl exit code 42")
      case result of
        CascadeAbort reason -> do
          reason `shouldContain` "K8s drain failed"
          reason `shouldContain` "kubectl exit code 42"
        _ -> expectationFailure ("expected CascadeAbort, got: " ++ show result)

    it "skip-is-success invariant: every CascadeContinue path returns no abort" $
      -- This codifies the doctrine's invariant: only DrainTimedOut and
      -- DrainFailed can produce CascadeAbort. If a future contributor
      -- adds a new DrainResult ctor that maps to CascadeAbort, this
      -- test still passes; if they accidentally map DrainSucceeded or
      -- DrainSkipped to CascadeAbort, this test fires.
      mapM_
        assertSkipIsSuccess
        [ ("DrainSucceeded", DrainSucceeded)
        , ("DrainSkipped \"x\"", DrainSkipped "x")
        ]

    it "Sprint 4.40 drain selector targets Delete-reclaim PVs, not Retain PVs" $ do
      deleteReclaimPersistentVolumeJsonPath
        `shouldContain` "persistentVolumeReclaimPolicy==\"Delete\""
      deleteReclaimPersistentVolumeJsonPath `shouldNotContain` "Retain"

    it "Sprint 4.40 parses only concrete Delete-reclaim PVC bindings" $
      deleteReclaimPvcBindings
        "prodbox|minio-0\nvault|vault-0\nmalformed\n|empty-namespace\nempty-name|\n"
        `shouldBe` [("prodbox", "minio-0"), ("vault", "vault-0")]

    it "Sprint 4.76 DrainUnobservable aborts rather than continuing" $ do
      let result = cascadeDecisionFromDrainResult (DrainUnobservable "kubeconfig context is stale")
      case result of
        CascadeAbort reason -> do
          reason `shouldContain` "could not observe"
          reason `shouldContain` "kubeconfig context is stale"
          reason `shouldNotContain` "nothing to drain"
        _ -> expectationFailure ("expected CascadeAbort, got: " ++ show result)

  describe "Sprint 4.76 three-valued cluster probe" $ do
    let probeOutput exitCode stderrText =
          Result.Success
            ProcessOutput
              { processExitCode = exitCode
              , processStdout = ""
              , processStderr = stderrText
              }
        assertClusterProbeUnobservable failureText =
          case classifyClusterProbe (probeOutput (ExitFailure 7) failureText) of
            ClusterUnobservable _ -> pure ()
            other -> expectationFailure ("expected ClusterUnobservable, got: " ++ show other)

    it "a serving API server is reachable" $
      classifyClusterProbe (probeOutput ExitSuccess "")
        `shouldBe` ClusterReachable

    it "a stopped installed RKE2 API is unobservable, never cluster-absent" $ do
      let probe =
            classifyClusterProbe
              ( probeOutput
                  (ExitFailure 1)
                  "The connection to the server 127.0.0.1:6443 was refused - did you specify the right host or port?\ndial tcp 127.0.0.1:6443: connect: connection refused\n"
              )
      case probe of
        ClusterUnobservable detail -> detail `shouldContain` "control plane is not serving"
        other -> expectationFailure ("expected ClusterUnobservable, got: " ++ show other)

    it "permission-denied is UNOBSERVABLE, not absence" $ do
      -- The Sprint 4.76 defect in one case: `clusterReachable :: IO Bool`
      -- returned False here, and the caller read False as "the cluster is
      -- gone". Being refused proves a server answered.
      let probe =
            classifyClusterProbe
              ( probeOutput
                  (ExitFailure 1)
                  "error: You must be logged in to the server (Unauthorized)\n"
              )
      case probe of
        ClusterUnobservable detail -> detail `shouldContain` "Unauthorized"
        _ -> expectationFailure ("expected ClusterUnobservable, got: " ++ show probe)

    it "transport, DNS, routing, auth, and malformed-context failures all stay unknown" $
      forM_
        [ "connect: no route to host"
        , "connect: network is unreachable"
        , "dial tcp: lookup stopped.example: no such host"
        , "error: You must be logged in to the server (Unauthorized)"
        , "Error from server (Forbidden): access denied"
        , "current-context is not set"
        , "server could not find the requested resource"
        , "something nobody has seen before"
        ]
        assertClusterProbeUnobservable

    it "a probe that could not be started is unobservable" $
      case classifyClusterProbe (Result.Failure "kubectl: no such file") of
        ClusterUnobservable detail -> detail `shouldContain` "kubectl"
        other -> expectationFailure ("expected ClusterUnobservable, got: " ++ show other)

  describe "K8s drain exact-target and readback safety" $ do
    it "missing exact kubeconfig refuses before ambient context can participate" $
      withSystemTempDirectory "prodbox-drain-missing-kubeconfig" $ \tmpDir -> do
        let exactPath = tmpDir </> "missing-rke2.yaml"
        prepared <-
          prepareK8sDrainEnvWithKubectl
            (tmpDir </> "must-not-run-kubectl")
            exactPath
            [("KUBECONFIG", "/tmp/hostile-ambient.yaml")]
            (Just tmpDir)
        case prepared of
          Left detail -> do
            detail `shouldContain` exactPath
            detail `shouldContain` "ambient KUBECONFIG"
          Right _ -> expectationFailure "expected missing exact kubeconfig to fail closed"

    it "uses one explicit kubeconfig and observes all accepted deletes before success" $
      withSystemTempDirectory "prodbox-drain-exact-target" $ \tmpDir -> do
        let kubeconfigPath = tmpDir </> "exact-rke2.yaml"
            kubectlPath = tmpDir </> "kubectl"
            invocationLog = tmpDir </> "kubectl.log"
        writeFile kubeconfigPath "apiVersion: v1\nkind: Config\n"
        writeFile
          kubectlPath
          ( unlines
              [ "#!/bin/sh"
              , "printf 'env=%s' \"${KUBECONFIG-unset}\" >> \"$DRAIN_LOG\""
              , "for arg in \"$@\"; do printf ' %s' \"$arg\" >> \"$DRAIN_LOG\"; done"
              , "printf '\\n' >> \"$DRAIN_LOG\""
              , "case \"$3:$4\" in"
              , "  get:pv) printf 'ns|claim\\n' ;;"
              , "  get:services) printf 'ns/lb\\n' ;;"
              , "  get:ingresses) printf 'ns/ing\\n' ;;"
              , "  get:pvc) printf 'persistentvolumeclaim/claim\\n' ;;"
              , "esac"
              ]
          )
        makeExecutable kubectlPath
        prepared <-
          prepareK8sDrainEnvWithKubectl
            kubectlPath
            kubeconfigPath
            [ ("KUBECONFIG", "/tmp/hostile-one.yaml")
            , ("DRAIN_LOG", invocationLog)
            , ("KUBECONFIG", "/tmp/hostile-two.yaml")
            ]
            (Just tmpDir)
        case prepared of
          Left detail -> expectationFailure detail
          Right drainEnv -> do
            result <- drainAwsAffectingK8sResources drainEnv (DrainTimeout 0)
            result
              `shouldBe` DrainTimedOut
                [ "Service/ns/lb"
                , "Ingress/ns/ing"
                , "PersistentVolumeClaim/ns/claim"
                ]
            logText <- readFile' invocationLog
            let invocations = lines logText
            invocations `shouldSatisfy` (not . null)
            forM_ invocations $ \invocation -> do
              take 3 (words invocation)
                `shouldBe` ["env=unset", "--kubeconfig", kubeconfigPath]
              length (filter (== "--kubeconfig") (words invocation)) `shouldBe` 1
            logText `shouldContain` " delete services "
            logText `shouldContain` " delete ingresses "
            logText `shouldContain` " delete pvc -n ns claim "
            logText `shouldContain` " get services "
            logText `shouldContain` " get ingresses "
            logText `shouldContain` " get pvc -n ns claim "

  describe "Sprint 5.28 dns-aws validation hosted-zone ownership" $ do
    it "projects only validation-owned zones out of a listing" $ do
      let payload =
            "{\"HostedZones\":[\
            \{\"Id\":\"/hostedzone/Z1\",\"Name\":\"prodbox-dns-aws-abc.example.invalid.\"},\
            \{\"Id\":\"/hostedzone/Z2\",\"Name\":\"operator-owned.example.invalid.\"},\
            \{\"Id\":\"/hostedzone/Z3\",\"Name\":\"prodbox-dns-aws-def.example.invalid.\"}]}"
      Route53ValidationZone.parseHostedZoneListing payload
        `shouldBe` Right
          [ ("/hostedzone/Z1", "prodbox-dns-aws-abc.example.invalid.")
          , ("/hostedzone/Z3", "prodbox-dns-aws-def.example.invalid.")
          ]

    it "leaves an operator-owned zone alone when nothing is validation-owned" $
      Route53ValidationZone.parseHostedZoneListing
        "{\"HostedZones\":[{\"Id\":\"/hostedzone/Z9\",\"Name\":\"operator.example.invalid.\"}]}"
        `shouldBe` Right []

    it "refuses an undecodable listing rather than reporting nothing to sweep" $
      Route53ValidationZone.parseHostedZoneListing "not json"
        `shouldSatisfy` either (const True) (const False)

    -- Sprint 4.85: the zone is billable and was created carrying no tag at
    -- all, so the terminal escape audit returned it from no query — a leaked
    -- zone was structurally invisible to the audit that exists to find it.
    it "Sprint 4.85 authors owned tags the terminal audit actually queries" $ do
      Prodbox.CheckCode.codeCreatedResourceFieldOfViewViolations `shouldBe` []

      -- Not vacuous: the zone authors a real family, and it is the one the
      -- catalog matches as an exact pair.
      OwnedResourceTags.dnsValidationHostedZoneTags
        `shouldSatisfy` elem OwnedResourceTags.prodboxManagedByTag
      OwnedResourceTags.codeCreatedAwsResourceTags
        OwnedResourceTags.DnsValidationHostedZone
        `shouldBe` OwnedResourceTags.dnsValidationHostedZoneTags

      -- It must classify as an escapee if it leaks, so it carries none of the
      -- retention markers the audit's carve-out keys on.
      map fst OwnedResourceTags.dnsValidationHostedZoneTags
        `shouldSatisfy` all (`notElem` ["prodbox.io/role", "prodbox.io/substrate"])

    it "Sprint 4.85 tags the zone through the bare id the tagging API takes" $ do
      -- create-hosted-zone returns /hostedzone/ZONEID; the tagging API takes
      -- the bare id, and passing the returned form would fail at the boundary.
      Route53ValidationZone.bareHostedZoneId "/hostedzone/Z123ABC" `shouldBe` "Z123ABC"
      Route53ValidationZone.bareHostedZoneId "Z123ABC" `shouldBe` "Z123ABC"
      Route53ValidationZone.validationHostedZoneTagCommand "/hostedzone/Z123ABC"
        `shouldBe` [ "route53"
                   , "change-tags-for-resource"
                   , "--resource-type"
                   , "hostedzone"
                   , "--resource-id"
                   , "Z123ABC"
                   , "--add-tags"
                   , "Key=prodbox.io/managed-by,Value=prodbox"
                   , "Key=prodbox.io/lifecycle,Value=per-run"
                   , "Key=prodbox.io/purpose,Value=dns-validation-zone"
                   ]

    it "derives the zone name and caller reference from one prefix" $ do
      Route53ValidationZone.validationHostedZoneName "abc" "example.invalid"
        `shouldBe` "prodbox-dns-aws-abc.example.invalid"
      Route53ValidationZone.validationHostedZoneCallerReference "abc"
        `shouldBe` "prodbox-dns-aws-abc"

    it "registers the zone in the lifecycle-class SSoT as per-run" $
      lookup "dns-aws-validation-hosted-zone" ResourceClass.resourceLifecycleClasses
        `shouldBe` Just ResourceClass.PerRun

  describe "Sprint 2.41 supervised-worker negative space" $ do
    let daemonPath = "src/Prodbox/Gateway/Daemon.hs"
        supervised =
          unlines
            [ "import Control.Concurrent.Async qualified as Async"
            , "import Control.Concurrent.Async (race, replicateConcurrently)"
