  describe "Sprint 4.13 prodbox nuke renderer + confirmation literal" $ do
    it "confirmation literal is `NUKE EVERYTHING` (case-sensitive, no shorthand)" $
      Nuke.confirmationLiteral `shouldBe` "NUKE EVERYTHING"
    it "renderNukePlan lists the signed external decommission gates and nodes" $ do
      let plan = Nuke.renderNukePlan "/tmp/repo"
      plan `shouldContain` "EXTERNAL_RECEIPT=<required-for-apply>"
      plan `shouldContain` "PINNED_RUNNER=<derived-from-external-receipt>.runner"
      plan `shouldContain` "GATE=freeze admission"
      plan `shouldContain` "GATE=create/fsync/read-back external receipt"
      plan `shouldContain` "NODE=ses-consumer-quiescence"
      plan `shouldContain` "NODE=tls-retained-objects"
      plan `shouldContain` "NODE=total-decommission-escape-audit"
      plan `shouldContain` "NODE=home-substrate-uninstall"
      -- Sprint 4.85: apply requires an explicit retain-or-delete decision, and
      -- `--dry-run` renders the requirement rather than a default.
      plan `shouldContain` "LOCAL_DATA=<required-for-apply>"
      plan `shouldContain` "NODE=local-data-disposition (<required-for-apply>)"
      plan `shouldContain` "NODE=terminal-receipt (unique terminal)"
      plan
        `shouldContain` "ADMIN_CREDENTIAL_SOURCE=one ephemeral admin AWS credential from the interactive prompt; never persisted"
      plan `shouldContain` "CONFIRMATION_LITERAL=NUKE EVERYTHING"
    it "pins non-empty compiled dependency and verifier metadata" $ do
      Nuke.nukeRunnerDependencyMetadata `shouldSatisfy` (not . BS.null)
      Nuke.nukeRunnerDependencyMetadata
        `shouldSatisfy` BS8.isInfixOf "prodbox-decommission-runner-dependencies-v1"
      Nuke.nukeRunnerDependencyMetadata
        `shouldSatisfy` BS8.isInfixOf "serialise="
      Nuke.nukeVerifierMetadata `shouldSatisfy` isRight
    it "advertises apply only through the complete production composition" $
      case Nuke.productionDecommissionAvailability of
        Nuke.ProductionDecommissionReady _ -> pure ()
    it "contains no reachable legacy teardown adapters" $ do
      source <- readFile "src/Prodbox/CLI/Nuke.hs"
      mapM_
        (source `shouldNotContain`)
        [ "runNativeDeleteCascade"
        , "runPulumiCommand"
        , "applyAwsTeardown"
        , "destroyLongLivedPulumiStateBucket"
        ]
    it "Sprint 4.76: carries the terminal tag sweep doctrine assigns it" $ do
      -- Standard C. This assertion previously ran with the opposite
      -- polarity: `discoverClusterTaggedAwsResources` sat in the
      -- forbidden list above, pinning the absence of the sweep that
      -- lifecycle_reconciliation_doctrine.md § 5 (the nuke row) and § 6b
      -- ("appends terminal absence and the required scoped tag sweep")
      -- have always assigned to this command. The sweep is not one of the
      -- legacy five-command adapters; it is a terminal obligation, and it
      -- is fail-closed with no retained-long-lived carve-out.
      source <- readFile "src/Prodbox/CLI/Nuke.hs"
      source `shouldContain` "discoverClusterTaggedAwsResources"
      source `shouldContain` "TagSweepNuke"
      -- Sprint 4.85: the sweep is no longer an out-of-band tail that ran after
      -- the runner returned success. It is the read-back half of the receipt
      -- graph's terminal node, so a crash or a lost response resumes through
      -- the manifest instead of leaving a converged-on-paper run whose only
      -- no-escape proof was never taken.
      source `shouldNotContain` "runNukeTerminalTagSweep"
      source `shouldContain` "productionFinalNoRetentionAuditCapability"

