    { DaemonEvents.eventId = DaemonEvents.EventId eventName
    , DaemonEvents.eventAggregateId = DaemonEvents.AggregateId "aggregate-a"
    , DaemonEvents.eventType = DaemonEvents.EventType "heartbeat"
