      ++ gatewaySecretRefType
      ++ ", session_token : Optional "
      ++ gatewaySecretRefType
      ++ ", region : Text }"
  ]

gatewayMinioCredsNoneLines :: [String]
gatewayMinioCredsNoneLines =
